    18	function BaseUserDetailsTooltip({accountID, fallbackUserDetails, icon, delegateAccountID, shiftHorizontal, children}: UserDetailsTooltipProps) {
    19	    const styles = useThemeStyles();
    20	    const {translate} = useLocalize();
    21	    const personalDetails = usePersonalDetails();
    22	    const otherPersonalDetails = useOtherPersonalDetails();
    23	    const [session] = useOnyx(ONYXKEYS.SESSION);
    24	    const isCurrentUserAnonymous = session?.accountID === accountID && isAnonymousUser(session);
    25	
    26	    const userDetails = personalDetails?.[accountID] ?? fallbackUserDetails ?? {};
    27	    const otherUserDetails = otherPersonalDetails?.[accountID] ?? {};
    28	    let userDisplayName = ReportUtils.getUserDetailTooltipText(accountID, userDetails.displayName ? userDetails.displayName.trim() : '');
    29	    let userLogin = !isCurrentUserAnonymous && userDetails.login?.trim() && userDetails.login !== userDetails.displayName ? Str.removeSMSDomain(userDetails.login) : '';
    30	
    31	    let userAvatar = otherUserDetails.avatar; // tooltip should read avatar from another source
    32	    let userAccountID = accountID;
    33	
    34	    // We replace the actor's email, name, and avatar with the Copilot manually for now. This will be improved upon when
    35	    // the Copilot feature is implemented.
    36	    if (delegateAccountID && delegateAccountID > 0) {
    37	        const delegateUserDetails = personalDetails?.[delegateAccountID];
    38	        const delegateUserDisplayName = ReportUtils.getUserDetailTooltipText(delegateAccountID);
    39	        userDisplayName = `${delegateUserDisplayName} (${translate('reportAction.asCopilot')} ${userDisplayName})`;
    40	        userLogin = delegateUserDetails?.login ?? '';
    41	        userAvatar = delegateUserDetails?.avatar;
    42	        userAccountID = delegateAccountID;
    43	    }
    44	
    45	    let title = String(userDisplayName).trim() ? userDisplayName : '';
    46	    let subtitle = userLogin.trim() && LocalePhoneNumber.formatPhoneNumber(userLogin) !== userDisplayName ? Str.removeSMSDomain(userLogin) : '';
    47	    if (icon && (icon.type === CONST.ICON_TYPE_WORKSPACE || !title)) {
    48	        title = icon.name ?? '';
    49	
    50	        // We need to clear the subtitle for workspaces so that we don't display any user details under the workspace name
    51	        if (icon.type === CONST.ICON_TYPE_WORKSPACE) {
    52	            subtitle = '';
    53	        }
    54	    }
    55	    if (CONST.RESTRICTED_ACCOUNT_IDS.includes(userAccountID) || CONST.RESTRICTED_EMAILS.includes(userLogin.trim())) {
    56	        subtitle = '';
    57	    }
    58	    const renderTooltipContent = useCallback(
    59	        () => (
    60	            <View style={[styles.alignItemsCenter, styles.ph2, styles.pv2]}>
    61	                <View style={styles.emptyAvatar}>
    62	                    <Avatar
    63	                        containerStyles={[styles.actionAvatar]}
    64	                        source={icon?.source ?? userAvatar}
    65	                        avatarID={icon?.id ?? userAccountID}
    66	                        type={icon?.type ?? CONST.ICON_TYPE_AVATAR}
    67	                        name={icon?.name ?? userLogin}
    68	                        fallbackIcon={icon?.fallbackIcon}
    69	                    />
    70	                </View>
    71	                <Text style={[styles.mt2, styles.textMicroBold, styles.textReactionSenders, styles.textAlignCenter]}>{title}</Text>
    72	                <Text style={[styles.textMicro, styles.fontColorReactionLabel, styles.breakWord, styles.textAlignCenter]}>{subtitle}</Text>
    73	            </View>
    74	        ),
    75	
    76	        [
    77	            styles.alignItemsCenter,
    78	            styles.ph2,
    79	            styles.pv2,
    80	            styles.emptyAvatar,
    81	            styles.actionAvatar,
    82	            styles.mt2,
    83	            styles.textMicroBold,
    84	            styles.textReactionSenders,
    85	            styles.textAlignCenter,
    86	            styles.textMicro,
    87	            styles.fontColorReactionLabel,
    88	            styles.breakWord,
    89	            icon,
    90	            userAvatar,
    91	            userAccountID,
    92	            userLogin,
    93	            title,
    94	            subtitle,
    95	        ],
    96	    );
    97	
    98	    if (!icon && !userDisplayName && !userLogin) {
    99	        return children;
   100	    }
   101	
   102	    return (
   103	        <Tooltip
   104	            shiftHorizontal={shiftHorizontal}
   105	            renderTooltipContent={renderTooltipContent}
   106	            renderTooltipContentKey={[userDisplayName, userLogin]}
   107	            shouldHandleScroll
   108	        >
   109	            {children}
   110	        </Tooltip>
   111	    );
   112	}
