{"command":"create","path":"/home/****/***/My_Openhands_Lancer/***/workspace/concerns_openai_gemini-2.5-pro/App_work/src/libs/actions/PersonalDetails.test.ts","file_text":"import Onyx from 'react-native-onyx';
import ONYXKEYS from '../../ONYXKEYS';
import * as PersonalDetails from './PersonalDetails';
import * as UserUtils from '../UserUtils';
import CONST from '../../CONST';
import { optimisticData, successData, failureData } from './PersonalDetails';

// Mock the API layer
jest.mock('../API', () => ({
  write: jest.fn(),
}));

describe('PersonalDetails', () => {
  beforeAll(() => {
    Onyx.init({
      keys: ONYXKEYS,
    });
  });

  afterEach(() => {
    Onyx.clear();
  });

  describe('updateAvatar', () => {
    it('should update the avatar in both PERSONAL_DETAILS_LIST and PERSONAL_DETAILS', () => {
      // Given
      const currentUserAccountID = 1;
      const file = { uri: 'test.jpg', name: 'test.jpg' };
      const expectedAvatarUrl = 'test.jpg';

      Onyx.set(ONYXKEYS.SESSION, { accountID: currentUserAccountID });

      // When
      PersonalDetails.updateAvatar(file);

      // Then
      const personalDetailsList = Onyx.get(ONYXKEYS.PERSONAL_DETAILS_LIST);
      const personalDetails = Onyx.get(ONYXKEYS.PERSONAL_DETAILS);

      expect(personalDetailsList[currentUserAccountID].avatar).toBe(expectedAvatarUrl);
      expect(personalDetails[currentUserAccountID].avatar).toBe(expectedAvatarUrl);
    });
  });

  describe('deleteAvatar', () => {
    it('should set the default avatar in both PERSONAL_DETAILS_LIST and PERSONAL_DETAILS', () => {
      // Given
      const currentUserAccountID = 1;
      const defaultAvatar = UserUtils.getDefaultAvatarURL(currentUserAccountID);

      Onyx.set(ONYXKEYS.SESSION, { accountID: currentUserAccountID });
      Onyx.set(ONYXKEYS.PERSONAL_DETAILS_LIST, {
        [currentUserAccountID]: { avatar: 'test.jpg' },
      });
      Onyx.set(ONYXKEYS.PERSONAL_DETAILS, {
        [currentUserAccountID]: { avatar: 'test.jpg' },
      });

      // When
      PersonalDetails.deleteAvatar();

      // Then
      const personalDetailsList = Onyx.get(ONYXKEYS.PERSONAL_DETAILS_LIST);
      const personalDetails = Onyx.get(ONYXKEYS.PERSONAL_DETAILS);

